private executeQueryCombination(query: QueryCombination, searchOptions: SearchOptions): RawResult {
  const options = { ...searchOptions, filter: undefined, ...query, queries: undefined }
  const results = query.queries.map((subquery) => this.executeQuery(subquery, options))
  const combined = this.combineResults(results, options.combineWith)

  if (options.filter) {
    this.applyFilterToResults(combined, options.filter)
  }

  return combined
}

private executeStringQuery(query: string, searchOptions: SearchOptions): RawResult {
  const { tokenize, processTerm, searchOptions: globalSearchOptions } = this._options
  const options = { tokenize, processTerm, ...globalSearchOptions, ...searchOptions }
  const { tokenize: searchTokenize, processTerm: searchProcessTerm } = options

  const terms = searchTokenize(query)
    .flatMap((term: string) => searchProcessTerm(term))
    .filter((term) => !!term) as string[]

  const queries: QuerySpec[] = terms.map(termToQuerySpec(options))
  const results = queries.map(query => this.executeQuerySpec(query, options))

  return this.combineResults(results, options.combineWith)
}

private applyFilterToResults(results: RawResult, filter: (result: SearchResult) => boolean): void {
  for (const [docId, rawValue] of results) {
    const result = this.makeResult(docId, rawValue)
    if (!filter(result)) results.delete(docId)
  }
}

